//! capstone 5 register-access rules (see access.rs). Generated by
//! `cargo run --profile fast --example disasm_detail_diff -- learn DIR --only
//! real64,real32,sweep64,sweep32,rand64,rand32,mut64,mut32` from capstone's detail output
//! (bench/scripts/disasm_detail_diff.py gen / gen-mut); regenerate rather than hand-edit.
//!
//! Line grammar:  MNEMONIC [COND...] = ACCESS | IMPLICIT_READ | IMPLICIT_WRITE
//!   COND     k:KINDS (operand kinds, e.g. k:rm) | s:SIG (full signature, e.g. s:r4,m4,i1:
//!            r1 r2 r4 r8 GPRs, rs rc rd rf rq rx ry rz rk rb segment / control / debug / x87 /
//!            mmx / xmm / ymm / zmm / mask / bound registers, m<size> memory, i<size> immediate)
//!            | m32 | m64 | p:PREFIX (printed prefix: - lock rep repe repne bnd repz notrack ...)
//!            | c:CTX (mandatory prefixes np 66 f3 f2 66f3 66f2, +w for REX.W; EVEX e ez eb ezb
//!            (zero-masking / EVEX.b); VEX / XOP v vw) | a16 a32 a64 (address size)
//!            | o:OPC (opcode bytes [/modrm.reg], e.g. o:f6/1)
//!   ACCESS   one digit per capstone detail operand: 0 none, 1 read, 2 write, 3 read+write
//!            ("-" when there are no operands)
//!   IMPLICIT comma separated capstone register names, "flags" (eflags/rflags), "*ax".."*di" /
//!            "*ip" (native size: rax/eax, ... rip/eip)
//! The first matching rule of a mnemonic wins; `MANUAL` is tried before `SPEC`.

/// Hand-written rules, tried before the learned ones: cases the learner cannot see because
/// capstone's detail output is not deterministic for them.
pub(crate) const MANUAL: &str = r#"
# capstone reports an uninitialised memory operand size for bndmk (so the learner skips it)
bndmk = 21 |  |
"#;

